private spawnFood(): void {
  const totalCells = COLS * ROWS
  // 蛇身占比超过 50% 时直接走全盘扫描，避免大量无效随机采样
  if (this.snake.length > totalCells / 2) {
    const free: Cell[] = []
    for (let cy = 0; cy < ROWS; cy += 1) {
      for (let cx = 0; cx < COLS; cx += 1) {
        if (!this.isOnSnake(cx, cy)) free.push({ x: cx, y: cy })
      }
    }
    if (free.length === 0) {
      this.endRun('win')
      return
    }
    const cell = free[Math.floor(Math.random() * free.length)] as Cell
    this.food = { x: cell.x, y: cell.y }
    this.setFoodPosition()
    return
  }
  let x = 0
  let y = 0
  let found = false
  for (let i = 0; i < 512 && !found; i += 1) {
    x = randInt(0, COLS - 1)
    y = randInt(0, ROWS - 1)
    found = !this.isOnSnake(x, y)
  }
  if (!found) {
    const free: Cell[] = []
    for (let cy = 0; cy < ROWS; cy += 1) {
      for (let cx = 0; cx < COLS; cx += 1) {
        if (!this.isOnSnake(cx, cy)) free.push({ x: cx, y: cy })
      }
    }
    if (free.length === 0) {
      this.endRun('win')
      return
    }
    const cell = free[Math.floor(Math.random() * free.length)] as Cell
    x = cell.x
    y = cell.y
  }
  this.food = { x, y }
  this.setFoodPosition()
}
